namespace{namespace c=fg_custom_block1_bot0;std::vector<std::uint8_t>ReadB(const std::filesystem::path&p){std::ifstream s(p,std::ios::binary|std::ios::ate);auto n=s.tellg();std::vector<std::uint8_t>b(static_cast<std::size_t>(n));s.seekg(0);s.read((char*)b.data(),n);return b;}
void Rec(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::vector<std::uint8_t>&i0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::vector<std::uint8_t>&i1,const std::vector<std::uint8_t>&out,std::size_t mm,std::size_t cc,const std::string&dev){std::ofstream s(p);bool pass=mm==0&&cc==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-block1-bot0-run.v1\",\n  \"backend\": \"mac-metal\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<getpid()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-000082\",\n  \"module_token\": 65,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"metal_function\": \"fg_custom_block1_bot0\",\n  \"selected_rtx_grid\": [40, 46, 1],\n  \"selected_rtx_block\": [32, 2, 6],\n  \"metal_dispatch_threads\": [320, 184, 48],\n  \"metal_threads_per_threadgroup\": [8, 4, 1],\n  \"weight_source_token\": 198,\n  \"bias_source_token\": 200,\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-block1-bot0-v1\",\n  \"input_pre_sha256\": \""<<Sha256(i0)<<"\",\n  \"input_post_sha256\": \""<<Sha256(i1)<<"\",\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mm<<",\n  \"canary_mismatched_bytes\": "<<cc<<",\n  \"external_model_files_opened\": true,\n  \"expected_output_file_opened\": false,\n  \"device_name\": \""<<dev<<"\",\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}}
int main(int argc,const char*v[]){@autoreleasepool{if(argc!=7)return 2;try{auto w0=ReadB(v[2]),b0=ReadB(v[3]),i0=c::Input();if(w0.size()!=c::kWeightBytes||Sha256(w0)!=c::kWeightSha256||b0.size()!=c::kBiasBytes||Sha256(b0)!=c::kBiasSha256)throw std::runtime_error("identity");char*e=nullptr;auto q=strtoul(v[6],&e,16);if(e==v[6]||*e||q>255)throw std::runtime_error("poison");auto poison=std::uint8_t(q);std::filesystem::path dir=v[4];std::filesystem::create_directories(dir);id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*er=nil;id<MTLLibrary>lib=[d newLibraryWithURL:[NSURL fileURLWithPath:[NSString stringWithUTF8String:v[1]]] error:&er];if(!lib)throw std::runtime_error(er.localizedDescription.UTF8String);id<MTLFunction>fn=[lib newFunctionWithName:@"fg_custom_block1_bot0"];id<MTLComputePipelineState>pipe=[d newComputePipelineStateWithFunction:fn error:&er];if(!pipe)throw std::runtime_error(er.localizedDescription.UTF8String);id<MTLBuffer>w=Guarded(d,&w0,c::kWeightBytes,0),b=Guarded(d,&b0,c::kBiasBytes,0),in=Guarded(d,&i0,c::kInputBytes,0),o0=Guarded(d,nullptr,c::kOutputPlaneBytes,poison),o1=Guarded(d,nullptr,c::kOutputPlaneBytes,poison),o2=Guarded(d,nullptr,c::kOutputPlaneBytes,poison);id<MTLCommandBuffer>cmd=[[d newCommandQueue]commandBuffer];id<MTLComputeCommandEncoder>enc=[cmd computeCommandEncoder];[enc setComputePipelineState:pipe];[enc setBuffer:w offset:kGuardBytes atIndex:0];[enc setBuffer:b offset:kGuardBytes atIndex:1];[enc setBuffer:in offset:kGuardBytes atIndex:2];[enc setBuffer:o0 offset:kGuardBytes atIndex:3];[enc setBuffer:o1 offset:kGuardBytes atIndex:4];[enc setBuffer:o2 offset:kGuardBytes atIndex:5];[enc dispatchThreads:MTLSizeMake(320,184,48) threadsPerThreadgroup:MTLSizeMake(8,4,1)];[enc endEncoding];[cmd commit];[cmd waitUntilCompleted];if(cmd.status==MTLCommandBufferStatusError)throw std::runtime_error(cmd.error.localizedDescription.UTF8String);auto w1=Payload(w,c::kWeightBytes),b1=Payload(b,c::kBiasBytes),i1=Payload(in,c::kInputBytes),a=Payload(o0,c::kOutputPlaneBytes),bb=Payload(o1,c::kOutputPlaneBytes),cc=Payload(o2,c::kOutputPlaneBytes);std::vector<std::uint8_t>out;out.reserve(c::kOutputBytes);out.insert(out.end(),a.begin(),a.end());out.insert(out.end(),bb.begin(),bb.end());out.insert(out.end(),cc.begin(),cc.end());auto mm=Mismatches(w0,w1)+Mismatches(b0,b1)+Mismatches(i0,i1);auto can=CanaryMismatches(w,c::kWeightBytes)+CanaryMismatches(b,c::kBiasBytes)+CanaryMismatches(in,c::kInputBytes)+CanaryMismatches(o0,c::kOutputPlaneBytes)+CanaryMismatches(o1,c::kOutputPlaneBytes)+CanaryMismatches(o2,c::kOutputPlaneBytes);Rec(dir/"run-receipt.json",v[5],poison,w0,b0,i0,w1,b1,i1,out,mm,can,d.name.UTF8String);Write(dir/"output.bin",out);bool pass=mm==0&&can==0;std::cout<<"output_sha256="<<Sha256(out)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}}
